import type { Category, Task } from '../types';

interface TaskCardProps {
  task: Task;
  category?: Category;
  completed?: boolean;
  onToggle?: () => void;
  showXp?: boolean;
  disabled?: boolean;
}

const frequencyLabels: Record<Task['frequency'], string> = {
  daily: 'Daily',
  weekly: 'Weekly',
  once: 'One-time',
};

export function TaskCard({
  task,
  category,
  completed = false,
  onToggle,
  showXp = true,
  disabled = false,
}: TaskCardProps) {
  return (
    <article
      className={`task-card${completed ? ' task-card--done' : ''}${disabled ? ' task-card--disabled' : ''}`}
    >
      <label className="task-card__label">
        {onToggle && (
          <input
            type="checkbox"
            checked={completed}
            disabled={disabled}
            onChange={onToggle}
            className="task-card__check"
          />
        )}
        <motion.div className="task-card__body">
          <div className="task-card__top">
            {category && (
              <span
                className="task-card__badge"
                style={{ borderColor: category.color, color: category.color }}
              >
                {category.icon} {category.name}
              </span>
            )}
            <span className="task-card__freq">{frequencyLabels[task.frequency]}</span>
          </div>
          <h3 className="task-card__title">{task.title}</h3>
          <p className="task-card__desc">{task.description}</p>
          <div className="task-card__meta">
            <span>Lvl. {task.minLevel}+</span>
            {task.durationMinutes && <span>{task.durationMinutes} min</span>}
            {showXp && <span className="task-card__xp">+{task.xpReward} XP</span>}
          </div>
        </motion.div>
      </label>
    </article>
  );
}

import { Link } from 'react-router-dom';
import { StatCard } from '../components/StatCard';
import { XpBar } from '../components/XpBar';
import { useAppStore } from '../hooks/useAppStore';
import { completionStats, getTodayPlan } from '../lib/gameLogic';
import { todayKey } from '../lib/dates';

export function Dashboard() {
  const { state, closeDay } = useAppStore();
  const { progress, levels } = state;
  const levelInfo = levels.find((l) => l.number === progress.currentLevel);
  const plan = getTodayPlan(state);
  const stats = completionStats(plan);
  const date = todayKey(state.settings.resetHour);
  const activePunishments = state.punishments.filter((p) => p.active).length;

  return (
    <div className="page">
      <section className="card card--hero">
        <XpBar
          totalXp={progress.totalXp}
          levels={levels}
          levelName={`Level ${progress.currentLevel} — ${levelInfo?.name ?? ''}`}
        />
      </section>

      <section className="stats-grid">
        <StatCard label="Streak" value={`${progress.streak} d`} hint="consecutive days" accent="#f9a8d4" />
        <StatCard label="Points" value={progress.points} hint="shop" accent="#c4b5fd" />
        <StatCard label="Today" value={`${stats.percent}%`} hint={`${stats.completed}/${stats.total} tasks`} />
        <StatCard label="Quota" value={`${state.settings.dailyQuotaPercent}%`} hint="daily goal" />
      </section>

      <section className="card">
        <h2 className="section-title">Quick actions</h2>
        <motion.div className="btn-row">
          <Link to="/today" className="btn btn--primary">
            View today&apos;s plan
          </Link>
          {!plan?.closed && stats.total > 0 && (
            <button type="button" className="btn btn--ghost" onClick={closeDay}>
              Close the day
            </button>
          )}
        </motion.div>
        {plan?.closed && (
          <p className="muted">Day {date} closed.</p>
        )}
      </section>

      {activePunishments > 0 && (
        <section className="card card--warn">
          <h2 className="section-title">Warning</h2>
          <p>
            {activePunishments} active punishment(s).{' '}
            <Link to="/punishments">View punishments</Link>
          </p>
        </section>
      )}

      <section className="card">
        <h2 className="section-title">Recent badges</h2>
        {state.unlockedRewardIds.length === 0 ? (
          <p className="muted">Complete your goals to unlock rewards.</p>
        ) : (
          <ul className="badge-list">
            {state.unlockedRewardIds.slice(-3).map((id) => {
              const r = state.rewards.find((x) => x.id === id);
              return r ? <li key={id}>🏅 {r.title}</li> : null;
            })}
          </ul>
        )}
      </section>
    </div>
  );
}

import type { CSSProperties } from 'react';
import { TaskCard } from '../components/TaskCard';
import { useAppStore } from '../hooks/useAppStore';
import { completionStats, getTodayPlan } from '../lib/gameLogic';
import { formatDisplayDate, todayKey } from '../lib/dates';

export function Today() {
  const { state, completeTask, uncompleteTask, closeDay } = useAppStore();
  const plan = getTodayPlan(state);
  const stats = completionStats(plan);
  const dateKey = todayKey(state.settings.resetHour);

  if (!plan) {
    return (
      <div className="page">
        <p className="muted">Loading plan…</p>
      </div>
    );
  }

  const earnedXp = plan.tasks
    .filter((t) => t.completed)
    .reduce((sum, entry) => {
      const task = state.tasks.find((x) => x.id === entry.taskId);
      return sum + (task?.xpReward ?? 0);
    }, 0);

  return (
    <div className="page">
      <header className="page-header">
        <h2>Today</h2>
        <p className="muted">{formatDisplayDate(dateKey)}</p>
      </header>

      <section className="card progress-summary">
        <motion.div
          className="progress-ring"
          style={{ '--p': stats.percent } as CSSProperties}
        >
          <span className="progress-ring__value">{stats.percent}%</span>
        </motion.div>
        <div>
          <p>
            <strong>{stats.completed}</strong> / {stats.total} tasks
          </p>
          <p className="muted">+{earnedXp} XP earned today</p>
          <p className="muted">
            Goal: {state.settings.dailyQuotaPercent}% of plan
          </p>
        </div>
      </section>

      <ul className="task-list">
        {plan.tasks.map((entry) => {
          const task = state.tasks.find((t) => t.id === entry.taskId);
          if (!task) return null;
          const category = state.categories.find((c) => c.id === task.categoryId);
          return (
            <li key={entry.taskId}>
              <TaskCard
                task={task}
                category={category}
                completed={entry.completed}
                disabled={plan.closed}
                onToggle={() =>
                  entry.completed
                    ? uncompleteTask(entry.taskId)
                    : completeTask(entry.taskId)
                }
              />
            </li>
          );
        })}
      </ul>

      {plan.tasks.length === 0 && (
        <p className="muted">No daily tasks for your level.</p>
      )}

      {!plan.closed && plan.tasks.length > 0 && (
        <button type="button" className="btn btn--primary btn--block" onClick={closeDay}>
          Close the day
        </button>
      )}

      {plan.closed && (
        <p className="notice">
          {stats.percent >= state.settings.dailyQuotaPercent
            ? 'Well done! Quota reached for today.'
            : 'Day closed without quota — punishments may apply.'}
        </p>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { TaskCard } from '../components/TaskCard';
import { useAppStore } from '../hooks/useAppStore';

export function Library() {
  const { state } = useAppStore();
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [levelFilter, setLevelFilter] = useState<number>(0);

  const filtered = useMemo(() => {
    return state.tasks.filter((t) => {
      if (categoryFilter !== 'all' && t.categoryId !== categoryFilter) return false;
      if (levelFilter > 0 && t.minLevel !== levelFilter) return false;
      return true;
    });
  }, [state.tasks, categoryFilter, levelFilter]);

  const grouped = useMemo(() => {
    const map = new Map<number, typeof filtered>();
    for (const t of filtered) {
      const list = map.get(t.minLevel) ?? [];
      list.push(t);
      map.set(t.minLevel, list);
    }
    return [...map.entries()].sort((a, b) => a[0] - b[0]);
  }, [filtered]);

  return (
    <div className="page">
      <header className="page-header">
        <h2>Library</h2>
        <p className="muted">Browse all tasks by category and level</p>
      </header>

      <div className="filters">
        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          aria-label="Filter by category"
        >
          <option value="all">All categories</option>
          {state.categories.map((c) => (
            <option key={c.id} value={c.id}>
              {c.icon} {c.name}
            </option>
          ))}
        </select>
        <select
          value={levelFilter}
          onChange={(e) => setLevelFilter(Number(e.target.value))}
          aria-label="Filter by level"
        >
          <option value={0}>All levels</option>
          {[1, 2, 3, 4, 5].map((n) => (
            <option key={n} value={n}>
              Level {n}
            </option>
          ))}
        </select>
      </div>

      {grouped.map(([level, tasks]) => (
        <section key={level} className="library-section">
          <h3 className="library-level">Level {level}</h3>
          <ul className="task-list">
            {tasks.map((task) => {
              const category = state.categories.find((c) => c.id === task.categoryId);
              const locked = task.minLevel > state.progress.currentLevel;
              return (
                <li key={task.id}>
                  <TaskCard
                    task={task}
                    category={category}
                    showXp
                    disabled={locked}
                  />
                  {locked && <p className="locked-hint">Unlocks at level {task.minLevel}</p>}
                </li>
              );
            })}
          </ul>
        </section>
      ))}
    </div>
  );
}

import { useAppStore } from '../hooks/useAppStore';

export function Rewards() {
  const { state, purchaseReward } = useAppStore();
  const { progress, unlockedRewardIds } = state;

  const badges = state.rewards.filter((r) => r.autoTrigger);
  const shop = state.rewards.filter((r) => r.cost != null);

  return (
    <div className="page">
      <header className="page-header">
        <h2>Rewards</h2>
        <p className="muted">{progress.points} points available</p>
      </header>

      <section className="card">
        <h3 className="section-title">Badges</h3>
        <ul className="reward-list">
          {badges.map((reward) => {
            const earned = unlockedRewardIds.includes(reward.id);
            return (
              <li
                key={reward.id}
                className={`reward-item${earned ? ' reward-item--earned' : ''}`}
              >
                <span className="reward-icon">{earned ? '🏅' : '🔒'}</span>
                <div>
                  <strong>{reward.title}</strong>
                  <p className="muted">{reward.description}</p>
                  {reward.autoTrigger?.type === 'streak' && (
                    <small>Streak: {reward.autoTrigger.days} days</small>
                  )}
                  {reward.autoTrigger?.type === 'level' && (
                    <small>Level {reward.autoTrigger.level}</small>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      </section>

      <section className="card">
        <h3 className="section-title">Shop</h3>
        <ul className="reward-list">
          {shop.map((reward) => {
            const owned = unlockedRewardIds.includes(reward.id);
            const canBuy = !owned && progress.points >= (reward.cost ?? 0);
            return (
              <li key={reward.id} className="reward-item">
                <span className="reward-icon">🎁</span>
                <div className="reward-item__body">
                  <strong>{reward.title}</strong>
                  <p className="muted">{reward.description}</p>
                  <span className="cost">{reward.cost} pts</span>
                </div>
                {owned ? (
                  <span className="tag tag--ok">Purchased</span>
                ) : (
                  <button
                    type="button"
                    className="btn btn--small"
                    disabled={!canBuy}
                    onClick={() => purchaseReward(reward.id)}
                  >
                    Buy
                  </button>
                )}
              </li>
            );
          })}
        </ul>
      </section>
    </motion.div>
  );
}

