import { useAppStore } from '../hooks/useAppStore';

export function Punishments() {
  const { state, dismissPunishment } = useAppStore();
  const active = state.punishments.filter((p) => p.active);
  const history = state.punishments.filter((p) => !p.active).slice(-10).reverse();

  return (
    <div className="page">
      <header className="page-header">
        <h2>Punishments</h2>
        <p className="muted">Up to 2 punishments per day if you miss the quota</p>
      </header>

      {active.length === 0 ? (
        <section className="card card--success">
          <p>No active punishments. Keep it up! ✨</p>
        </section>
      ) : (
        <ul className="punishment-list">
          {active.map((p) => (
            <li key={p.id} className="card card--warn punishment-item">
              <h3>{p.title}</h3>
              <p>{p.description}</p>
              {p.pointsLost > 0 && (
                <p className="punishment-points">−{p.pointsLost} points</p>
              )}
              <p className="muted">Assigned on {p.date}</p>
              <button
                type="button"
                className="btn btn--ghost btn--small"
                onClick={() => dismissPunishment(p.id)}
              >
                Mark as completed
              </button>
            </li>
          ))}
        </ul>
      )}

      {history.length > 0 && (
        <section className="card">
          <h3 className="section-title">Recent history</h3>
          <ul className="history-list">
            {history.map((p) => (
              <li key={p.id}>
                <span>{p.title}</span>
                <span className="muted">{p.date}</span>
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}

import { useState } from 'react';
import type { Category, Task, TaskFrequency } from '../types';
import { useAppStore } from '../hooks/useAppStore';

function newId(): string {
  return `custom-${Date.now()}`;
}

export function Settings() {
  const {
    state,
    updateSettings,
    updateCategory,
    addCategory,
    updateTask,
    addTask,
    resetAll,
  } = useAppStore();

  const [tab, setTab] = useState<'rules' | 'categories' | 'tasks'>('rules');

  return (
    <div className="page">
      <header className="page-header">
        <h2>Settings</h2>
      </header>

      <div className="tabs">
        <button
          type="button"
          className={tab === 'rules' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('rules')}
        >
          Rules
        </button>
        <button
          type="button"
          className={tab === 'categories' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('categories')}
        >
          Categories
        </button>
        <button
          type="button"
          className={tab === 'tasks' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('tasks')}
        >
          Tasks
        </button>
      </div>

      {tab === 'rules' && (
        <section className="card">
          <label className="field">
            <span>Daily quota (%)</span>
            <input
              type="number"
              min={50}
              max={100}
              value={state.settings.dailyQuotaPercent}
              onChange={(e) =>
                updateSettings({ dailyQuotaPercent: Number(e.target.value) })
              }
            />
          </label>
          <label className="field">
            <span>Reset hour (0–23)</span>
            <input
              type="number"
              min={0}
              max={23}
              value={state.settings.resetHour}
              onChange={(e) => updateSettings({ resetHour: Number(e.target.value) })}
            />
          </label>
          <p className="muted">
            The day starts after this hour. The plan regenerates automatically.
          </p>
          <button type="button" className="btn btn--danger" onClick={resetAll}>
            Reset all data
          </button>
        </section>
      )}

      {tab === 'categories' && (
        <CategoryEditor
          categories={state.categories}
          onSave={updateCategory}
          onAdd={addCategory}
        />
      )}

      {tab === 'tasks' && (
        <TaskEditor
          tasks={state.tasks}
          categories={state.categories}
          onSave={updateTask}
          onAdd={addTask}
        />
      )}
    </div>
  );
}

function CategoryEditor({
  categories,
  onSave,
  onAdd,
}: {
  categories: Category[];
  onSave: (c: Category) => void;
  onAdd: (c: Category) => void;
}) {
  const [draft, setDraft] = useState<Category>({
    id: '',
    name: '',
    icon: '✨',
    color: '#f9a8d4',
    description: '',
  });

  const submit = () => {
    if (!draft.name.trim()) return;
    const cat = { ...draft, id: draft.id || newId() };
    if (categories.some((c) => c.id === cat.id)) onSave(cat);
    else onAdd(cat);
    setDraft({ id: '', name: '', icon: '✨', color: '#f9a8d4', description: '' });
  };

  return (
    <section className="card">
      <ul className="edit-list">
        {categories.map((c) => (
          <li key={c.id}>
            <button type="button" className="edit-list__btn" onClick={() => setDraft(c)}>
              {c.icon} {c.name}
            </button>
          </li>
        ))}
      </ul>
      <div className="form-grid">
        <input
          placeholder="Name"
          value={draft.name}
          onChange={(e) => setDraft({ ...draft, name: e.target.value })}
        />
        <input
          placeholder="Icon"
          value={draft.icon}
          onChange={(e) => setDraft({ ...draft, icon: e.target.value })}
        />
        <input
          type="color"
          value={draft.color}
          onChange={(e) => setDraft({ ...draft, color: e.target.value })}
        />
        <input
          placeholder="Description"
          value={draft.description}
          onChange={(e) => setDraft({ ...draft, description: e.target.value })}
        />
      </div>
      <button type="button" className="btn btn--primary" onClick={submit}>
        Save category
      </button>
    </section>
  );
}

function TaskEditor({
  tasks,
  categories,
  onSave,
  onAdd,
}: {
  tasks: Task[];
  categories: Category[];
  onSave: (t: Task) => void;
  onAdd: (t: Task) => void;
}) {
  const [draft, setDraft] = useState<Task>({
    id: '',
    title: '',
    description: '',
    categoryId: categories[0]?.id ?? '',
    minLevel: 1,
    xpReward: 10,
    frequency: 'daily',
  });

  const submit = () => {
    if (!draft.title.trim()) return;
    const task = { ...draft, id: draft.id || newId() };
    if (tasks.some((t) => t.id === task.id)) onSave(task);
    else onAdd(task);
    setDraft({
      id: '',
      title: '',
      description: '',
      categoryId: categories[0]?.id ?? '',
      minLevel: 1,
      xpReward: 10,
      frequency: 'daily',
    });
  };

  return (
    <section className="card">
      <ul className="edit-list">
        {tasks.map((t) => (
          <li key={t.id}>
            <button type="button" className="edit-list__btn" onClick={() => setDraft(t)}>
              {t.title}
            </button>
          </li>
        ))}
      </ul>
      <div className="form-grid">
        <input
          placeholder="Title"
          value={draft.title}
          onChange={(e) => setDraft({ ...draft, title: e.target.value })}
        />
        <input
          placeholder="Description"
          value={draft.description}
          onChange={(e) => setDraft({ ...draft, description: e.target.value })}
        />
        <select
          value={draft.categoryId}
          onChange={(e) => setDraft({ ...draft, categoryId: e.target.value })}
        >
          {categories.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
        <input
          type="number"
          min={1}
          max={5}
          value={draft.minLevel}
          onChange={(e) => setDraft({ ...draft, minLevel: Number(e.target.value) })}
        />
        <input
          type="number"
          min={5}
          value={draft.xpReward}
          onChange={(e) => setDraft({ ...draft, xpReward: Number(e.target.value) })}
        />
        <select
          value={draft.frequency}
          onChange={(e) =>
            setDraft({ ...draft, frequency: e.target.value as TaskFrequency })
          }
        >
          <option value="daily">Daily</option>
          <option value="weekly">Weekly</option>
          <option value="once">One-time</option>
        </select>
      </div>
      <button type="button" className="btn btn--primary" onClick={submit}>
        Save task
      </button>
    </section>
  );
}
